head.script:
scwin.trigger1_onclick = function(e) {
    wc.createWindow("123123", null, "gridView_windowContainer_tooltip_WEFF-317_(WSQ-3627)_sub.xml", "", "ededed");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 2. text컬럼의 입력필드에 마우스를 더블클릭(edit모드)하고 키보드의 방향키(위,아래,좌,우)를 각각 실행한다.
    //2. Double-click (edit mode) on the input field of the text column and execute the direction keys (up, down, left, right) of the keyboard respectively.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wc_subWindow0').prop('title') == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
